    deepExplanation: "```ts\ntype SignupInput = {\n  email: string;\n  age: number;\n};\n\ntype ValidationResult =\n  | { valid: true; data: SignupInput }\n  | {\n      valid: false;\n      fieldErrors: Record<string, string>;\n      formError?: string;\n    };\n\nfunction validateClient(input: SignupInput): ValidationResult {\n  const fieldErrors: Record<string, string> = {};\n\n  if (!input.email.includes(\"@\")) {\n    fieldErrors.email = \"Invalid email\";\n  }\n\n  if (input.age < 18) {\n    fieldErrors.age = \"Must be 18 or older\";\n  }\n\n  return Object.keys(fieldErrors).length\n    ? { valid: false, fieldErrors }\n    : { valid: true, data: input };\n}\n```\n\nThe same business rules should be validated on the server, typically through a shared schema or server-side implementation.",
