    deepExplanation: "tsx\nfunction UsernameField() {\n  const [username, setUsername] = useState(\"\");\n  const [status, setStatus] =\n    useState<\"idle\" | \"checking\" | \"available\" | \"taken\">(\"idle\");\n\n  useEffect(() => {\n    if (!username) {\n      setStatus(\"idle\");\n      return;\n    }\n\n    const controller = new AbortController();\n    setStatus(\"checking\");\n\n    fetch(`/api/users/availability?name=${encodeURIComponent(username)}`, {\n      signal: controller.signal,\n    })\n      .then(r => r.json())\n      .then(result => {\n        setStatus(result.available ? \"available\" : \"taken\");\n      })\n      .catch(error => {\n        if (error.name !== \"AbortError\") {\n          setStatus(\"idle\");\n        }\n      });\n\n    return () => controller.abort();\n  }, [username]);\n\n  return <input value={username} onChange={e => setUsername(e.target.value)} />;\n}\n```\n\nIn production, debounce or validate on blur, and make the final submit authoritative.",
